+  if (!Number.isSafeInteger(maxBytes) || maxBytes < 0) {
+    throw new Error('maxBytes must be a nonnegative safe integer');
+  }
+  if (!Array.isArray(sections)) {
+    throw new Error('sections must be an array');
+  }
+
+  const ids = new Set();
+  const validated = [];
+
+  // Validate and frame every entry before making any packing decision.
+  for (let index = 0; index < sections.length; index += 1) {
+    if (!Object.prototype.hasOwnProperty.call(sections, index)) {
+      throw new Error(`sections must be dense (missing index ${index})`);
+    }
+
+    const section = sections[index];
+    if (section === null || typeof section !== 'object' || Array.isArray(section)) {
+      throw new Error(`section at index ${index} must be a non-null, non-array object`);
+    }
+    for (const field of ['id', 'text', 'priority', 'required']) {
+      if (!Object.prototype.hasOwnProperty.call(section, field)) {
+        throw new Error(`section at index ${index} is missing ${field}`);
+      }
+    }
+
+    const {id, text, priority, required} = section;
+    if (typeof id !== 'string' || id.length === 0) {
+      throw new Error(`section at index ${index} has an invalid id`);
+    }
+    if (typeof text !== 'string') {
+      throw new Error(`section at index ${index} has invalid text`);
+    }
+    if (!Number.isSafeInteger(priority) || priority < 0) {
+      throw new Error(`section at index ${index} has an invalid priority`);
+    }
+    if (typeof required !== 'boolean') {
+      throw new Error(`section at index ${index} has an invalid required flag`);
+    }
+    if (ids.has(id)) {
+      throw new Error(`duplicate section id at index ${index}`);
+    }
+    ids.add(id);
+
+    const frame = `### ${JSON.stringify(id)}\n${text}\n`;
+    validated.push({
+      id,
+      priority,
+      required,
+      index,
+      frame,
+      cost: Buffer.byteLength(frame, 'utf8'),
+    });
+  }
+
+  let remaining = maxBytes;
+  let bytes = 0;
+  const frames = [];
+  const included = [];
+  const selectedOptional = new Set();
+
+  for (const section of validated) {
+    if (!section.required) continue;
+    if (section.cost > remaining) {
+      throw new Error('required sections exceed maxBytes');
+    }
+    frames.push(section.frame);
+    included.push(section.id);
+    bytes += section.cost;
+    remaining -= section.cost;
+  }
+
+  const optional = validated
+    .filter((section) => !section.required)
+    .sort((a, b) => b.priority - a.priority || a.index - b.index);
+
+  for (const section of optional) {
+    if (section.cost > remaining) continue;
+    frames.push(section.frame);
+    included.push(section.id);
+    selectedOptional.add(section.index);
+    bytes += section.cost;
+    remaining -= section.cost;
+  }
+
+  const omitted = validated
+    .filter((section) => !section.required && !selectedOptional.has(section.index))
+    .map((section) => section.id);
+
+  return {text: frames.join(''), bytes, included, omitted};
 }
+
+function runCli() {
+  if (process.argv.length !== 3) {
+    throw new Error('usage: node context-packet.js INPUT_JSON_FILE');
+  }
+
+  const bytes = readFileSync(process.argv[2]);
+  const input = JSON.parse(new TextDecoder('utf-8', {fatal: true}).decode(bytes));
+  if (input === null || typeof input !== 'object' || Array.isArray(input)) {
+    throw new Error('input JSON must be an object');
+  }
+  const result = packContext(input.sections, input.maxBytes);
+  process.stdout.write(`${JSON.stringify(result)}\n`);
+}
+
+const isMain = process.argv[1] !== undefined
+  && import.meta.url === pathToFileURL(process.argv[1]).href;
+
+if (isMain) {
+  try {
+    runCli();
+  } catch (error) {
+    const message = error instanceof Error ? error.message : String(error);
+    process.stderr.write(`context-packet: ${message || 'unknown error'}\n`);
+    process.exitCode = 2;
+  }
+}

